// fetch() with a Bun.file body (sent from the file as it goes) and a slice of one: the server
// gets every byte, and Content-Length says how many
import { file, serve } from "bun";
import { writeFileSync, mkdtempSync } from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import { join } from "node:path";

export default async function run() {
  const path = join(mkdtempSync(join(tmpdir(), "tov-upload-")), "data.bin");
  const data = new Uint8Array(3 * 1024 * 1024 + 17);
  for (let i = 0; i < data.length; i++) data[i] = (i * 31 + (i >> 8)) & 255;
  writeFileSync(path, data);
  const sha = (b) => createHash("sha256").update(b).digest("hex");
  const server = serve({
    port: 0,
    async fetch(req) {
      const body = new Uint8Array(await req.arrayBuffer());
      return Response.json({ length: req.headers.get("content-length"), got: body.length, sha: sha(body) });
    },
  });
  const url = `http://127.0.0.1:${server.port}/`;
  const whole = await (await fetch(url, { method: "PUT", body: file(path) })).json();
  console.log("whole:", whole.length === String(data.length), whole.got === data.length, whole.sha === sha(data));
  const part = await (await fetch(url, { method: "POST", body: file(path).slice(1000, 300000) })).json();
  console.log("slice:", part.length === "299000", part.got === 299000, part.sha === sha(data.subarray(1000, 300000)));
  server.stop(true);
}
